Nous allons reprendre la classe `Arbre` réalisée dans la partie précédente grâce au module `py_libs.module_arbres`:

    ```python  
    class Arbre:
        def __init__(self, *args):
            """Création d'un arbre"""
            # Création d'un arbre vide
            if len(args) == 0:
                self.contenu = (None, None, None)

            # Création d'un arbre non vide       
            elif len(args) == 3:
                self.contenu = (args[0], args[1], args[2])

            # Création d'une feuille    
            elif len(args) == 1:
                self.contenu = (args[0] ,Arbre(), Arbre())

        def __repr__(self):
            """permet d'afficher l'arbre"""        
            return str(self.contenu)

        def __eq__(self, other):            
            """permet de vérifier si deux arbres sont égaux"""
            return self.contenu == other.contenu

        def droit(self):
            """Pour obtenir l'arbre droit"""        
            return self.contenu[2]

        def gauche(self):
            """Pour obtenir l'arbre gauche"""    
            return self.contenu[1]

        def etiquette(self):        
            """Pour obtenir l'etiquette"""
            return self.contenu[0]  

        def est_vide(self):
            """Vérifie si l'arbre est vide"""        
            return self.contenu == (None, None, None)

        def est_feuille(self):
            """Vérifie si l'arbre est une feuille"""  
            return not self.est_vide() and self.gauche().est_vide() and self.droit().est_vide()
    ```

