Vous disposez du module `py_libs.parcours` qui contient les parcours d'arbres binaires élaborés dans les chapitres précédents:

    ```python
    class File:
        """ Implémentation basique d'une file"""    

        def __init__(self):
            """Initialisation d'une file vide"""        
            self.contenu = [] 

        # Méthodes:               
        def enfiler(self, valeur):
            """enfile la valeur passée en paramètre et renvoie la file"""
            self.contenu.append(valeur)  
            return self

        def defiler(self):
            """defile la valeur au début de la file et renvoie la file"""
            if len(self.contenu) != 0:    
                self.contenu.pop(0)
            return self

        def premier(self):
            """Renvoie le premier élément au début de la file"""
            if len(self.contenu) == 0:
                return None
            return self.contenu[0]

        def est_vide(self):
            """Vérifie si la file est vide"""
            return self.contenu == []     

        # Méthodes spéciales:  
        def __len__(self):
            """donne la longueur de la file"""
            return len(self.contenu)

        def __repr__ (self): 
            """permet d'afficher la file"""
            return str(self.contenu)        

        def __eq__(self, other):            
            """permet de comparer deux files"""
            return self.contenu == other.contenu   


    def parcours_largeur(arbre):
        """
        Préconditions: Arbre de la classe "Arbre"
        Postconditions: Parcours en largeur de l'arbre (liste)
        """    
        if arbre.est_vide(): 
            return []
        parcours = []
        file = File()
        file.enfiler(arbre)

        while not file.est_vide():        
            nouvel_arbre = file.premier()        
            parcours.append(nouvel_arbre.etiquette())
            file.defiler()

            if not nouvel_arbre.gauche().est_vide():
                file.enfiler(nouvel_arbre.gauche())
            if not nouvel_arbre.droit().est_vide():
                file.enfiler(nouvel_arbre.droit())
        return parcours    

    def parcours_prefixe_arbre(arbre, parcours):
        """
        Préconditions: (Arbre)
        Postconditions: (Liste) parcours préfixe de l'arbre 
        """    
        if arbre.est_vide(): 
            return []
        else: 
            parcours.append(arbre.etiquette())
            parcours_prefixe_arbre(arbre.gauche(), parcours)
            parcours_prefixe_arbre(arbre.droit(), parcours)           
        return parcours


    def parcours_infixe_arbre(arbre, parcours):
        """
        Préconditions: (Arbre)
        Postconditions: (Liste) parcours infixe de l'arbre 
        """    
        if arbre.est_vide(): 
            return []
        else: 
            parcours_infixe_arbre(arbre.gauche(), parcours)
            parcours.append(arbre.etiquette())
            parcours_infixe_arbre(arbre.droit(), parcours)           
        return parcours

    def parcours_postfixe_arbre(arbre, parcours):
        """
        Préconditions: (Arbre)
        Postconditions: (Liste) parcours postfixe de l'arbre 
        """    
        if arbre.est_vide(): 
            return []
        else: 
            parcours_postfixe_arbre(arbre.gauche(), parcours)
            parcours_postfixe_arbre(arbre.droit(), parcours)
            parcours.append(arbre.etiquette())
        return parcours


    def taille(arbre):    
        '''
        Préconditions: Arbre de la classe "Arbre"
        Postconditions: (entier) taille de l'arbre 
        '''
        if arbre.est_vide():
            return 0
        else:        
            return 1 + taille(arbre.gauche()) + taille(arbre.droit())


    def hauteur(arbre):
        '''
        Préconditions: Arbre de la classe "Arbre"
        Postconditions: (entier) hauteur de l'arbre
        '''
        if arbre.est_vide():
            return -1
        else:
            return 1 + max(hauteur(arbre.gauche()), hauteur(arbre.droit()))    
    ```

