def variation_totale_mini_k(hauteurs, k):
    n = len(hauteurs)
    memo = [0 for _ in range(n)]
    for i in range(1, n):
        memo[i] = min(
            (memo[i - j] + abs(hauteurs[i] - hauteurs[i - j])
            for j in range(1, k + 1)
            if i - j >= 0)
        )
    return memo[n - 1]
```

